records.script:
if doc.director_approval_status != "Approved":
    frappe.throw(
        "Director approval is required before submitting the Purchase Order. "
        "Create a Purchase Approval task, get it completed as Approved, then submit."
    )

MAIN_WH = "Main - Inmed"

for row in (doc.items or []):
    if row.warehouse != MAIN_WH:
        frappe.throw(f"Receiving must be into {MAIN_WH}. Row warehouse is {row.warehouse or 'not set'}.")

    if not row.item_code:
        continue

    item = frappe.get_doc("Item", row.item_code)

    requires_expiry = bool(item.get("has_expiry_date"))
    has_batch = bool(item.get("has_batch_no"))

    if requires_expiry and has_batch:
        if not row.batch_no:
            frappe.throw(f"Row for item {row.item_code} requires Batch + Expiry. Batch No is missing.")

        batch = frappe.get_doc("Batch", row.batch_no)
        if not batch.expiry_date:
            frappe.throw(f"Batch {row.batch_no} must have Expiry Date for item {row.item_code}.")

if doc.supplier:
    for row in (doc.items or []):
        if not row.item_code:
            continue

        suppliers = frappe.get_all(
            "Item Supplier",
            filters={"parent": row.item_code, "parenttype": "Item"},
            pluck="supplier",
        )

        suppliers = [s for s in (suppliers or []) if s]

        if len(suppliers) != 1:
            frappe.throw(
                f"Item {row.item_code} must have exactly 1 Supplier (Doc 07 policy). Found: {', '.join(suppliers) or 'none'}."
            )

        if suppliers[0] != doc.supplier:
            frappe.throw(
                f"Item {row.item_code} supplier is {suppliers[0]} but PO supplier is {doc.supplier}. Do not mix suppliers on one PO."
            )

before = doc.get_doc_before_save()
if before:
    def snap(rows):
        return [(r.warehouse, r.warehouse_reorder_level or 0, r.warehouse_reorder_qty or 0) for r in (rows or [])]
    if snap(before.reorder_levels) != snap(doc.reorder_levels):
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw("Doc 08: Reorder Change Reason required.")

before = doc.get_doc_before_save()

if not before:
    pass
else:
    # Standard ERPNext fieldname for Item Reorder child table.
    # If your instance uses a different name, change this value.
    REORDER_FIELDNAME = "reorder_levels"

    def normalize(rows):
        out = []
        for r in (rows or []):
            out.append({
                "warehouse": r.warehouse,
                "reorder_level": float(getattr(r, "warehouse_reorder_level", 0) or 0),
                "reorder_qty": float(getattr(r, "warehouse_reorder_qty", 0) or 0),
            })
        return out

    before_rows = normalize(before.get(REORDER_FIELDNAME) or [])
    after_rows  = normalize(doc.get(REORDER_FIELDNAME) or [])

    if before_rows != after_rows:
        if not (doc.reorder_change_reason or "").strip():
            frappe.throw(
                "Reorder Change Reason is required when changing reorder thresholds "
                "(Doc 08 governance rule)."
            )

if not doc.case_items:
	frappe.throw('Add at least one item before submitting.')
if doc.status not in ('Draft', 'Confirmed'):
	frappe.throw('Cannot submit a Dispatch Case in status: ' + doc.status)
if doc.status == 'Draft':
	doc.status = 'Confirmed'
# Do NOT create Pack task here - it will be created when Order Entry task is completed

def run_script():
    task_name = frappe.form_dict.get('task_name')
    if not task_name:
        frappe.throw('Task is required.')
    task = frappe.get_doc('Task', task_name)
    # This API previously had NO acceptance check of any kind — the only guard
    # was that the client hid the button until the task was accepted, which is
    # not a guard at all. It creates a Dispatch Case and writes it back onto the
    # task, so it must be held to the same standard as the other task_* APIs.
    if (task.get('custom_accepted_by') or '') != frappe.session.user:
        frappe.throw('You must accept the task before creating a Dispatch Case.')
    if (task.get('task_kind') or '') != 'Order entry':
        frappe.throw('A Dispatch Case can only be created from an Order entry task.')
    if task.get('dispatch_case'):
        frappe.response['message'] = {'ok': True, 'dispatch_case': task.dispatch_case, 'created': False}
        return
    case = frappe.new_doc('Dispatch Case')
    if task.get('customer'):
        case.customer = task.customer
    case.status = 'Draft'
    case.order_entry_task = task_name
    if task.get('description'):
        case.notes = 'Created from Task ' + task.name + '\n\n' + task.description
    else:
        case.notes = 'Created from Task ' + task.name
    case.flags.ignore_permissions = True
    case.flags.ignore_mandatory = True
    case.insert()
    frappe.db.set_value('Task', task_name, 'dispatch_case', case.name)
    frappe.response['message'] = {'ok': True, 'dispatch_case': case.name, 'created': True}
run_script()

def run_script():
    barcode = (frappe.form_dict.get("barcode") or "").strip()
    if not barcode:
        frappe.throw("Barcode is required.")
    item_code = None
    if frappe.db.exists("Item", barcode):
        item_code = barcode
    if not item_code:
        item_code = frappe.db.get_value("Item Barcode", {"barcode": barcode}, "parent")
    frappe.response["message"] = {"ok": True, "barcode": barcode, "item_code": item_code}
run_script()

for row in doc.items:
    row.remaining_quantity = (row.won_quantity or 0) - (row.supplied_quantity or 0)

today = frappe.utils.getdate(frappe.utils.nowdate())
valid_from = frappe.utils.getdate(doc.valid_from) if doc.valid_from else None
valid_to = frappe.utils.getdate(doc.valid_to) if doc.valid_to else None
if doc.status == "Closed":
    pass
elif valid_from and valid_to:
    if today < valid_from:
        doc.status = "Draft"
    elif today >= valid_from and today <= valid_to:
        doc.status = "Active"
    elif today > valid_to:
        doc.status = "Expired"

if doc.docstatus == 1:
    hospital = doc.customer
    active_tenders = frappe.get_all(
        "Tender Agreement",
        filters={"hospital": hospital, "status": "Active"},
        fields=["name", "valid_from", "valid_to"],
        order_by="valid_to asc, valid_from asc, name asc",
    )

    if active_tenders:
        tender_docs = [frappe.get_doc("Tender Agreement", tender.name) for tender in active_tenders]
        fulfillment_rows = []

        for inv_item in doc.items:
            item_code = inv_item.item_code
            qty = inv_item.qty or 0
            if not item_code or qty <= 0:
                continue

            matches = []
            for tender in tender_docs:
                for tender_item in tender.items:
                    if tender_item.item_code == item_code:
                        matches.append({"tender": tender, "item": tender_item})

            if len(matches) > 1:
                tender_names = ", ".join(match["tender"].name for match in matches)
                frappe.throw(
                    f"Multiple active Tender Agreements found for hospital {hospital} and item {item_code}: {tender_names}. "
                    "Only one active tender per hospital/item is allowed. Close or expire the duplicate tender before submitting this invoice."
                )

            if len(matches) == 1:
                match = matches[0]
                tender = match["tender"]
                tender_item = match["item"]
                remaining = (tender_item.won_quantity or 0) - (tender_item.supplied_quantity or 0)

                if qty > remaining:
                    frappe.throw(
                        f"Tender {tender.name} has only {remaining} remaining for item {item_code}, but this invoice has quantity {qty}. "
                        "Review with Accounting/Director before changing the invoice or tender quantity."
                    )

                tender_item.supplied_quantity = (tender_item.supplied_quantity or 0) + qty
                tender_item.remaining_quantity = (tender_item.won_quantity or 0) - tender_item.supplied_quantity
                tender.flags.ignore_permissions = True
                tender.save()
                fulfillment_rows.append({
                    "tender_agreement": tender.name,
                    "item_code": item_code,
                    "quantity": qty,
                    "sales_invoice_item": inv_item.name,
                    "applied_at": frappe.utils.now_datetime(),
                })

        if fulfillment_rows:
            inv = frappe.get_doc("Sales Invoice", doc.name)
            inv.set("tender_fulfillments", [])
            for row in fulfillment_rows:
                inv.append("tender_fulfillments", row)
            inv.flags.ignore_permissions = True
            inv.save()

codes_text = frappe.form_dict.get("codes") or ""
codes = []
for part in codes_text.split(","):
    code = part.strip()
    if code:
        codes.append(code)

updated = []
missing = []
for code in codes:
    exists = frappe.db.exists("Item", code)
    if exists:
        frappe.db.set_value("Item", code, "has_batch_no", 0, update_modified=False)
        frappe.db.set_value("Item", code, "has_expiry_date", 0, update_modified=False)
        updated.append(code)
    else:
        missing.append(code)

frappe.response["message"] = {"updated": updated, "missing": missing, "count": len(updated)}

items = frappe.get_all("Item", fields=["name", "has_batch_no", "has_serial_no", "has_expiry_date"], limit_page_length=0)
changed = 0
for item in items:
    updates = {}
    if item.get("has_batch_no"):
        updates["has_batch_no"] = 0
    if item.get("has_serial_no"):
        updates["has_serial_no"] = 0
    if item.get("has_expiry_date"):
        updates["has_expiry_date"] = 0
    if updates:
        for fieldname, value in updates.items():
            frappe.db.set_value("Item", item.name, fieldname, value, update_modified=False)
        changed += 1
frappe.db.commit()
frappe.response["message"] = {"ok": True, "checked": len(items), "changed": changed}

# Triggers on Task (After Save)
# SAFEGUARD 1: Do not run on initial creation (only on updates)
before_doc = doc.get_doc_before_save()

if before_doc and doc.has_value_changed("status"):
    current_status = doc.status

    # SAFEGUARD 2: Only notify on key milestone statuses
    NOTIFIABLE_STATUSES = ["Working", "Completed", "Cancelled"]

    if current_status in NOTIFIABLE_STATUSES:
        current_user = frappe.session.user

        # Use task owner as the notification target (the person who created/delegated this task)
        assigner = doc.owner

        # SAFEGUARD 3: Prevent self-notifications
        if assigner and assigner != current_user:

            telegram_settings = frappe.get_doc("Telegram Settings")
            raw_token = telegram_settings.get_password("bot_token") or ""
            bot_token = raw_token.strip()
            if bot_token.lower().startswith("bot"):
                bot_token = bot_token[3:]

            if not bot_token:
                print(f"[TgStatus] {frappe.utils.now()} task={doc.name} SKIPPED: reason=no_token")
            else:
                # Read chat ID from User custom field
                chat_id = frappe.db.get_value("User", assigner, "telegram_chat_id")

                if chat_id:
                    status_icons = {
                        "Working": "Working",
                        "Completed": "Completed",
                        "Cancelled": "Cancelled"
                    }
                    status_display = status_icons.get(current_status, current_status)

                    updater_name = frappe.db.get_value("User", current_user, "full_name") or current_user
                    task_url = f"https://test.erpnext.am/app/task/{doc.name}"

                    message = (
                        f"Task Status Updated!\n\n"
                        f"*Task:* {doc.name}\n"
                        f"*New Status:* {status_display}\n"
                        f"*Updated By:* {updater_name}\n\n"
                        f"View Task: {task_url}"
                    )

                    url = f"https://api.telegram.org/bot{bot_token}/sendMessage"
                    payload = {
                        "chat_id": chat_id,
                        "text": message,
                        "parse_mode": "Markdown"
                    }
                    try:
                        frappe.make_post_request(url, json=payload)
                        print(f"[TgStatus] {frappe.utils.now()} task={doc.name} sent_to={assigner} status={current_status}")
                    except Exception as e:
                        frappe.log_error(
                            title="Status Notification Failed",
                            message=f"Error sending status update to {assigner}: {str(e)}"
                        )
                        print(f"[TgStatus] {frappe.utils.now()} task={doc.name} FAILED: user={assigner} error={str(e)}")
                else:
                    print(f"[TgStatus] {frappe.utils.now()} task={doc.name} SKIPPED: reason=no_chat_id user={assigner}")
        else:
            print(f"[TgStatus] {frappe.utils.now()} task={doc.name} SKIPPED: reason=self_notification user={current_user}")
    else:
        print(f"[TgStatus] {frappe.utils.now()} task={doc.name} status={current_status} SKIPPED: reason=not_notifiable")

if doc.get("task_kind") == "Other: Entry":
    if not doc.get("subject") or doc.get("subject") in ("New Task", "Other"):
        doc.subject = "Other: Entry"
elif doc.get("task_kind") == "Other: Processing":
    if not doc.get("subject") or doc.get("subject") in ("New Task", "Other"):
        doc.subject = "Other: Processing"

hospital = doc.customer
active_tenders = frappe.get_all(
    "Tender Agreement",
    filters={"hospital": hospital, "status": "Active"},
    fields=["name", "valid_from", "valid_to"],
    order_by="valid_to asc, valid_from asc, name asc",
)

if active_tenders:
    tender_docs = [frappe.get_doc("Tender Agreement", tender.name) for tender in active_tenders]

    for inv_item in doc.items:
        item_code = inv_item.item_code
        qty = inv_item.qty or 0
        if not item_code or qty <= 0:
            continue

        matches = []
        for tender in tender_docs:
            for tender_item in tender.items:
                if tender_item.item_code == item_code:
                    matches.append({"tender": tender, "item": tender_item})

        if len(matches) > 1:
            tender_names = ", ".join(match["tender"].name for match in matches)
            frappe.throw(
                f"Multiple active Tender Agreements found for hospital {hospital} and item {item_code}: {tender_names}. "
                "Only one active tender per hospital/item is allowed. Close or expire the duplicate tender before submitting this invoice."
            )

        if len(matches) == 1:
            match = matches[0]
            tender = match["tender"]
            tender_item = match["item"]
            remaining = (tender_item.won_quantity or 0) - (tender_item.supplied_quantity or 0)

            if qty > remaining:
                frappe.throw(
                    f"Tender {tender.name} has only {remaining} remaining for item {item_code}, but this invoice has quantity {qty}. "
                    "Review with Accounting/Director before changing the invoice or tender quantity."
                )

            tender_price = tender_item.tender_price or 0
            invoice_rate = inv_item.rate or 0
            if tender_price > 0 and frappe.utils.flt(invoice_rate, 2) != frappe.utils.flt(tender_price, 2):
                frappe.throw(
                    f"Item {item_code} is covered by Tender Agreement {tender.name}. "
                    f"Invoice rate must equal tender price {tender_price}, but current rate is {invoice_rate}."
                )

if doc.docstatus == 2:
    for fulfillment in (doc.get("tender_fulfillments") or []):
        tender_name = fulfillment.tender_agreement
        item_code = fulfillment.item_code
        qty = fulfillment.quantity or 0

        if not tender_name or not item_code or qty <= 0:
            continue

        tender = frappe.get_doc("Tender Agreement", tender_name)
        matched = False
        for tender_item in tender.items:
            if tender_item.item_code == item_code:
                supplied = tender_item.supplied_quantity or 0
                new_supplied = supplied - qty
                if new_supplied < 0:
                    new_supplied = 0
                tender_item.supplied_quantity = new_supplied
                tender_item.remaining_quantity = (tender_item.won_quantity or 0) - tender_item.supplied_quantity
                matched = True
                break

        if not matched:
            frappe.throw(
                f"Cannot reverse tender fulfillment for invoice {doc.name}: item {item_code} was not found in Tender Agreement {tender_name}."
            )

        tender.flags.ignore_permissions = True
        tender.save()

task_name = frappe.form_dict.get("task_name")
template_name = frappe.form_dict.get("template_name")
if not task_name or not template_name:
    frappe.throw("Task and template are required.")

task = frappe.get_doc("Task", task_name)
if (task.get("custom_accepted_by") or "") != frappe.session.user:
    frappe.throw("You must accept the task before making changes.")
if (task.get("task_kind") or "") != "Order entry":
    frappe.throw("A template can only be applied from an Order entry task.")
if not task.dispatch_case:
    frappe.throw("No Dispatch Case linked to this task.")

dc = frappe.get_doc("Dispatch Case", task.dispatch_case)
# Applying a template REPLACES all case items, so it must never run against a
# case that has already been submitted, packed or delivered.
if (dc.docstatus or 0) != 0:
    frappe.throw("This Dispatch Case is already submitted; a template cannot replace its products.")
if dc.status not in ("Draft", "Awaiting Approval"):
    frappe.throw("A template can only be applied while the Dispatch Case is in Draft or Awaiting Approval. Current status: " + str(dc.status))
template = frappe.get_doc("Surgical Kit Template", template_name)

dc.set("case_items", [])
for t_row in (template.template_items or []):
    dc.append("case_items", {
        "item_code": t_row.item_code,
        "item_name": t_row.item_name,
        "dispatched_qty": t_row.qty or 1,
    })

dc.flags.ignore_permissions = True
dc.save()

print(f"[Template] Applied template {template_name} to DC {dc.name}: {len(dc.case_items)} items")
frappe.response["message"] = {"ok": True, "items_count": len(dc.case_items)}
